/**
 * Standalone farmer AI chats (not tied to a symptom report).
 *
 * Each row is one message in a conversation. `conversation_id` groups the
 * messages and is generated by the backend when the first message is sent.
 * Ownership is always checked with `farmer_id` so one farmer can never read
 * another farmer's history.
 */
export default {
  version: 14,
  name: '013_ai_chat_messages',
  async up(db) {
    await db.batch(
      [
        `CREATE TABLE IF NOT EXISTS pashu_ai_chat_messages (
          id TEXT PRIMARY KEY,
          conversation_id TEXT NOT NULL,
          farmer_id TEXT NOT NULL,
          role TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
          content TEXT NOT NULL,
          created_at INTEGER NOT NULL
        )`,
        `CREATE INDEX IF NOT EXISTS idx_ai_chat_messages_farmer_conversation
          ON pashu_ai_chat_messages(farmer_id, conversation_id, created_at)`,
        `CREATE INDEX IF NOT EXISTS idx_ai_chat_messages_conversation
          ON pashu_ai_chat_messages(conversation_id, created_at)`,
      ],
      'write',
    );
  },
};
